function directBound(fn,ms=500){let timer;return Promise.race([Promise.resolve().then(fn),new Promise((_,reject)=>timer=setTimeout(()=>reject(Error('cache timeout')),ms))]).finally(()=>clearTimeout(timer));}
async function directCached(name,request){try{return await directBound(async()=>{const c=await caches.open(name);return c.match(request);});}catch(_){return null;}}
async function directPut(name,request,response){try{await directBound(async()=>{const c=await caches.open(name);await c.put(request,response);});return true;}catch(_){return false;}}
// Never persist dynamic cross-origin media: storage may be authorized for one account only.
async function directCleanLegacyMedia(){try{const cache=await caches.open(DIRECT.cache);for(const k of await cache.keys()){if(['res.cloudinary.com','firebasestorage.googleapis.com'].includes(new URL(k.url).hostname))await cache.delete(k);}await caches.delete(DIRECT.media);}catch(_){}}
async function directValid(response,record){if(!response||!record||!response.ok)return false;try{const bytes=await response.clone().arrayBuffer();if(bytes.byteLength!==record.size)return false;const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),x=>x.toString(16).padStart(2,'0')).join('');return hash===record.sha256;}catch(_){return false;}}
function directRecord(url){const key=url.href.slice(directScope.length);return DIRECT_RELEASE.resources.find(r=>r.url===key);}
async function directResponse(event){const request=event.request,url=new URL(request.url);if(request.mode==='navigate'){
 try{const response=await fetch(request);if(response.ok&&directRoot(url))event.waitUntil((async()=>{if(await directValid(response,DIRECT_RELEASE.entry))await directPut(DIRECT.docs,new URL('index.html',directScope).href,response);})());return response.clone();}
 catch(error){const cached=await directCached(DIRECT.docs,new URL('index.html',directScope).href);if(await directValid(cached,DIRECT_RELEASE.entry))return cached;return new Response('الاتصال غير متاح، ومفيش صفحة محفوظة على الجهاز لسه.',{status:503,headers:{'Content-Type':'text/plain; charset=utf-8'}});}
 }
 const immutable=url.origin===self.location.origin&&(url.pathname.startsWith(new URL('release/',directScope).pathname)||['direct-entry-bridge.js','forum-feed.js','lazy-sections.js','library-feed.js','notification-permission.js'].some(p=>url.pathname===new URL(p,directScope).pathname));
 const media=['res.cloudinary.com','firebasestorage.googleapis.com'].includes(url.hostname);
 if(immutable){const record=directRecord(url);try{const response=await fetch(request);if(record&&response.ok)event.waitUntil((async()=>{if(await directValid(response,record))await directPut(DIRECT.cache,request,response);})());return response.clone();}catch(error){const cached=await directCached(DIRECT.cache,request);if(await directValid(cached,record))return cached;throw error;}}
 if(media)return fetch(request,{cache:'no-store'});
 return fetch(request);
}
async function directPrepare(){const m=DIRECT_RELEASE;if(m.schema!==2||!/^[a-f0-9]{64}$/.test(m.generation)||!Array.isArray(m.resources)||m.resources.length>512||m.resources.reduce((n,r)=>n+r.size,0)>33554432)throw Error('manifest invalid');for(const r of m.resources){if(/\/(?:military|instructions|tuition-fees|expenses|study-schedule|sheetaty|my-docs)\.(?:js|css)(?:\?|$)/.test(r.url))continue;const url=new URL(r.url,directScope);if(url.origin!==self.location.origin||!url.href.startsWith(directScope)||!Number.isSafeInteger(r.size)||r.size<0||r.size>4194304||!/^[a-f0-9]{64}$/.test(r.sha256))throw Error('asset invalid');let res=await directCached(DIRECT.cache,url.href);if(!await directValid(res,r)){res=await fetch(url.href);if(!await directValid(res,r))throw Error('asset mismatch');if(!await directPut(DIRECT.cache,url.href,res))throw Error('cache unavailable');}}const doc=await fetch(new URL('index.html',directScope),{cache:'no-store'});if(await directValid(doc,m.entry))await directPut(DIRECT.docs,new URL('index.html',directScope).href,doc);}
self.addEventListener('install',event=>{ /* no application download or gate during install */ });
self.addEventListener('activate',event=>{event.waitUntil(directCleanLegacyMedia()); /* no takeover or reload */ });
self.addEventListener('message',event=>{if(event.data?.type!=='BIS_OFFLINE_PREPARE'||event.data.protocol!==2||event.data.generation!==DIRECT_RELEASE.generation||!event.source?.url?.startsWith(directScope))return;if(!DIRECT.pending)DIRECT.pending=directPrepare().catch(()=>{}).finally(()=>DIRECT.pending=null);event.waitUntil(DIRECT.pending);});
self.addEventListener('fetch',event=>{const r=event.request,u=new URL(r.url);if(r.method!=='GET')return;if(u.origin===self.location.origin&&u.href.startsWith(directScope)||['res.cloudinary.com','firebasestorage.googleapis.com'].includes(u.hostname)){
 // Extend lifetime synchronously. Deferred cache work cannot outlive the fetch event registration.
 const work=[];let finish;const lifetime=new Promise(resolve=>{finish=resolve;});event.waitUntil(lifetime);const pending=directResponse({request:r,waitUntil:p=>work.push(p)});event.respondWith(pending);pending.then(()=>finish(Promise.allSettled(work)),()=>finish(Promise.allSettled(work)));
}});
